import {Chess} from './vendor/chess.js';
export const opposite=c=>c==='w'?'b':'w';
export function repetition(chess){const h=chess.history({verbose:true});const key=f=>f.split(' ').slice(0,4).join(' ');return [h[0]?.before||chess.fen(),...h.map(m=>m.after)].filter(f=>key(f)===key(chess.fen())).length}
// Material test for flag fall. It does not adjudicate unusual blocked fortresses.
export function cannotMate(chess,color){const all=chess.board().flat().filter(Boolean),own=all.filter(p=>p.color===color),other=all.filter(p=>p.color!==color);if(own.some(p=>'pqr'.includes(p.type)))return false;if(own.some(p=>p.type==='n'))return own.length===2&&!other.some(p=>'pnbr'.includes(p.type));if(own.some(p=>p.type==='b')){const bishops=all.filter(p=>p.type==='b');return !all.some(p=>'pn'.includes(p.type))&&new Set(bishops.map(p=>(p.square.charCodeAt(0)+Number(p.square[1]))%2)).size===1}return true}
export class LiveGame{
 constructor({minutes=10,increment=0,white='Bianco',black='Nero',side=null}={},now=Date.now()){this.chess=new Chess();this.data={version:1,id:'live-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join(''),minutes,increment,white,black,side,remaining:{w:minutes*60000,b:minutes*60000},anchor:now,paused:false,result:'*',reason:'',offer:null,created:now};this.headers()}
 headers(){const d=this.data;for(const [k,v] of Object.entries({Event:'Plystreak · Gioco dal vivo',White:d.white,Black:d.black,Result:d.result,Date:new Date(d.created).toISOString().slice(0,10).replaceAll('-','.'),TimeControl:d.minutes?`${d.minutes*60}+${d.increment}`:'-'}))this.chess.setHeader(k,String(v))}
 static restore(raw){if(raw?.version!==1||typeof raw.pgn!=='string'||!['*','1-0','0-1','1/2-1/2'].includes(raw.result)||!Number.isFinite(raw.anchor)||!Number.isFinite(raw.minutes)||raw.minutes<0||!Number.isFinite(raw.increment)||raw.increment<0||!['w','b'].every(c=>Number.isFinite(raw.remaining?.[c])&&raw.remaining[c]>=0))throw Error('Salvataggio non valido');const g=Object.create(LiveGame.prototype);g.data=structuredClone(raw);g.chess=new Chess();g.chess.loadPgn(raw.pgn);return g}
 snapshot(){this.headers();return {...structuredClone(this.data),pgn:this.chess.pgn()}}
 remaining(color,now=Date.now()){const d=this.data;return Math.max(0,d.remaining[color]-(d.minutes&&d.result==='*'&&!d.paused&&this.chess.turn()===color?Math.max(0,now-d.anchor):0))}
 finish(result,reason,now=Date.now()){const c=this.chess.turn();this.data.remaining[c]=this.remaining(c,now);this.data.anchor=now;this.data.result=result;this.data.reason=reason;this.data.offer=null;this.headers()}
 tick(now=Date.now()){const d=this.data,c=this.chess.turn();if(d.minutes&&d.result==='*'&&!d.paused&&this.remaining(c,now)<=0){d.remaining[c]=0;const winner=opposite(c);this.finish(cannotMate(this.chess,winner)?'1/2-1/2':winner==='w'?'1-0':'0-1','Tempo esaurito',now);return true}return false}
 resign(now=Date.now()){if(this.tick(now)||this.data.result!=='*')return;const winner=opposite(this.chess.turn());this.finish(cannotMate(this.chess,winner)?'1/2-1/2':winner==='w'?'1-0':'0-1','Abbandono',now)}
 claimable(){return repetition(this.chess)>=3||Number(this.chess.fen().split(' ')[4])>=100}
 move(move,now=Date.now()){if(this.tick(now)||this.data.result!=='*'||this.data.paused)return null;const c=this.chess.turn(),left=this.remaining(c,now);let m;try{m=this.chess.move(move)}catch{return null}if(!m)return null;this.data.remaining[c]=left+(this.data.minutes?this.data.increment*1000:0);this.data.anchor=now;if(this.data.offer&&this.data.offer!==c)this.data.offer=null;if(this.chess.isCheckmate())this.finish(c==='w'?'1-0':'0-1','Scacco matto',now);else if(this.chess.isStalemate())this.finish('1/2-1/2','Stallo',now);else if(this.chess.isInsufficientMaterial())this.finish('1/2-1/2','Materiale insufficiente',now);else if(repetition(this.chess)>=5)this.finish('1/2-1/2','Quinta ripetizione',now);else if(Number(this.chess.fen().split(' ')[4])>=150)this.finish('1/2-1/2','Regola delle 75 mosse',now);return m}
 pause(now=Date.now()){if(this.tick(now)||this.data.result!=='*')return;const c=this.chess.turn();this.data.remaining[c]=this.remaining(c,now);this.data.paused=!this.data.paused;this.data.anchor=now}
 claim(move){let c=this.chess;if(move){c=new Chess();c.loadPgn(this.chess.pgn());try{c.move(move)}catch{return false}}if(repetition(c)>=3||Number(c.fen().split(' ')[4])>=100){this.finish('1/2-1/2','Patta reclamata');return true}return false}
}
